//go:build ignore

// gen-errorcodes-docs renders docs/reference/error-codes.md from
// pkg/errors: AllCodes() gives the rows, Status() the HTTP status and
// Message() the meaning. Run via `make docs-generate`; `make docs-check`
// fails when the page differs from this output.
package main

import (
	"bytes"
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	pkgerr "github.com/bino-bi/sluice/pkg/errors"
)

const header = `<!-- SPDX-License-Identifier: CC-BY-4.0 -->
<!-- Generated by scripts/gen-errorcodes-docs.go. Do not edit by hand. -->

# Error codes

Sluice puts one of these codes in the ` + "`code`" + ` field of an error response.
MCP tool errors use the same codes.
[REST API](rest-api.md) shows the response body.

| Code | HTTP status | Meaning |
|---|---|---|
`

const footer = `
- ` + "`ERR_RESULT_TRUNCATED`" + ` is a warning in a successful response, not an error.
- A policy can replace ` + "`ACL_DENIED`" + ` or ` + "`ACL_REJECTED`" + ` with its own code. The HTTP status stays 403.
- Only ` + "`POST /admin/reload`" + ` returns ` + "`ERR_CONFIG_INVALID`" + ` and ` + "`ERR_POLICY_INVALID`" + `.
`

func main() {
	out := flag.String("out", "docs/reference/error-codes.md", "output path")
	check := flag.Bool("check", false, "fail instead of write when output differs")
	flag.Parse()

	var buf bytes.Buffer
	buf.WriteString(header)
	for _, c := range pkgerr.AllCodes() {
		fmt.Fprintf(&buf, "| `%s` | %d | %s |\n", c, pkgerr.Status(c), meaning(c))
	}
	buf.WriteString(footer)

	abs, err := filepath.Abs(*out)
	if err != nil {
		fatal("resolve path: %v", err)
	}

	if *check {
		cur, err := os.ReadFile(abs)
		if err != nil {
			fatal("read existing: %v", err)
		}
		if !bytes.Equal(cur, buf.Bytes()) {
			fmt.Fprintln(os.Stderr, "error-codes.md drift: run `make docs-generate`")
			os.Exit(1)
		}
		return
	}

	if err := os.WriteFile(abs, buf.Bytes(), 0o644); err != nil {
		fatal("write %s: %v", abs, err)
	}
	fmt.Printf("wrote %s\n", abs)
}

// meaning is the default message of the code, as a table cell.
func meaning(c pkgerr.Code) string {
	m := strings.ReplaceAll(pkgerr.Message(c), "|", `\|`)
	return strings.ToUpper(m[:1]) + m[1:]
}

func fatal(f string, args ...any) {
	fmt.Fprintf(os.Stderr, f+"\n", args...)
	os.Exit(1)
}
